// ---------- QR-facture suisse (norme SIX, version 2.0) ----------
const clean = (s, max) =>
  String(s || "")
    .replace(/[’‘`´]/g, "'")
    .replace(/[–—]/g, "-")
    .replace(/[“”«»]/g, '"')
    .replace(/[\r\n\t]+/g, " ")
    .replace(/[^\x20-\x7E\u00A0-\u00FF]/g, "")
    .trim()
    .slice(0, max);

function parseStreet(a) {
  const s = String(a || "").trim();
  const m = s.match(/^(.*?)[\s,]+(\d+\s?[A-Za-z]?(?:[-/]\d+[A-Za-z]?)?)$/);
  return m ? { street: m[1].trim(), no: m[2].replace(/\s/g, "") } : { street: s, no: "" };
}
function parseCity(c) {
  const s = String(c || "").trim();
  const m = s.match(/^(\S{2,16})\s+(.+)$/);
  return m ? { zip: m[1], town: m[2].trim() } : { zip: "", town: s };
}
function ibanOk(iban) {
  if (!/^[A-Z]{2}\d{2}[A-Z0-9]{11,30}$/.test(iban)) return false;
  const r = iban.slice(4) + iban.slice(0, 4);
  let rem = 0;
  for (const ch of r) {
    const v = /[A-Z]/.test(ch) ? String(ch.charCodeAt(0) - 55) : ch;
    for (const d of v) rem = (rem * 10 + Number(d)) % 97;
  }
  return rem === 1;
}
function qrrReference(number) {
  const digits = String(number).replace(/\D/g, "").slice(-26).padStart(26, "0");
  const t = [0, 9, 4, 6, 8, 2, 7, 1, 3, 5];
  let carry = 0;
  for (const ch of digits) carry = t[(carry + Number(ch)) % 10];
  return digits + ((10 - carry) % 10);
}
const groupIban = (i) => i.replace(/(.{4})/g, "$1 ").trim();
const groupQrr = (r) => r.replace(/^(\d{2})(\d{5})(\d{5})(\d{5})(\d{5})(\d{5})$/, "$1 $2 $3 $4 $5 $6");
const fmtSlipAmount = (a) => {
  const [i, d] = a.split(".");
  return i.replace(/\B(?=(\d{3})+(?!\d))/g, "\u00A0") + "." + d;
};

function buildSwissQR(inv) {
  const co = inv.company;
  const cl = inv.client || {};
  const errors = [];
  const iban = String(co.iban || "").replace(/\s/g, "").toUpperCase();
  if (!iban) errors.push("IBAN manquant (onglet Mon entreprise).");
  else if (!/^(CH|LI)/.test(iban) || iban.length !== 21) errors.push("L'IBAN doit être un IBAN suisse ou liechtensteinois de 21 caractères.");
  else if (!ibanOk(iban)) errors.push("L'IBAN saisi n'est pas valide (la clé de contrôle ne correspond pas).");
  const name = clean(co.nom, 70);
  const st = parseStreet(co.adresse);
  const ct = parseCity(co.npaLocalite);
  if (!name) errors.push("Nom de l'entreprise manquant.");
  if (!ct.zip || !ct.town) errors.push("NPA et localité de l'entreprise manquants (ex. 2800 Delémont).");

  const country = iban.slice(0, 2) === "LI" ? "LI" : "CH";
  const amount = inv.total > 0 ? inv.total.toFixed(2) : "";
  const iid = parseInt(iban.slice(4, 9), 10);
  const isQrIban = !errors.length && iid >= 30000 && iid <= 31999;
  const refType = isQrIban ? "QRR" : "NON";
  const ref = isQrIban ? qrrReference(inv.number) : "";
  const msg = clean(`Facture ${inv.number}`, 140);

  const dSt = parseStreet(cl.adresse);
  const dCt = parseCity(cl.npaLocalite);
  const dName = clean(cl.nom, 70);
  const debtor =
    dName && dCt.zip && dCt.town
      ? {
          name: dName,
          street: clean(dSt.street, 70),
          no: clean(dSt.no, 16),
          zip: clean(dCt.zip, 16),
          town: clean(dCt.town, 35),
          country: (clean(cl.pays || "CH", 2) || "CH").toUpperCase(),
        }
      : null;

  const parts = {
    iban, name,
    street: clean(st.street, 70), no: clean(st.no, 16),
    zip: clean(ct.zip, 16), town: clean(ct.town, 35),
    country, amount, refType, ref, msg, debtor, isQrIban,
  };
  const fields = [
    "SPC", "0200", "1", iban,
    "S", parts.name, parts.street, parts.no, parts.zip, parts.town, country,
    ...Array(7).fill(""),
    amount, "CHF",
    ...(debtor ? ["S", debtor.name, debtor.street, debtor.no, debtor.zip, debtor.town, debtor.country] : Array(7).fill("")),
    refType, ref, msg, "EPD",
  ];
  return { errors, parts, payload: fields.join("\r\n") };
}

const QR_URLS = [
  "https://cdnjs.cloudflare.com/ajax/libs/qrcode-generator/1.4.4/qrcode.min.js",
  "https://cdn.jsdelivr.net/npm/qrcode-generator@1.4.4/qrcode.js",
];
let qrLoading = null;
function loadQrLib() {
  if (window.qrcode) return Promise.resolve();
  if (qrLoading) return qrLoading;
  qrLoading = new Promise((resolve, reject) => {
    let i = 0;
    const next = () => {
      if (i >= QR_URLS.length) { qrLoading = null; reject(new Error("qr")); return; }
      const s = document.createElement("script");
      s.src = QR_URLS[i++];
      s.onload = () => resolve();
      s.onerror = () => { s.remove(); next(); };
      document.head.appendChild(s);
    };
    next();
  });
  return qrLoading;
}
function useQrLib() {
  const [state, setState] = useState("loading");
  useEffect(() => {
    let alive = true;
    loadQrLib()
      .then(() => {
        window.qrcode.stringToBytes = (s) => Array.from(new TextEncoder().encode(s));
        if (alive) setState("ready");
      })
      .catch(() => { if (alive) setState("error"); });
    return () => { alive = false; };
  }, []);
  return state;
}

function QrCode({ payload, mm }) {
  const lib = useQrLib();
  const data = useMemo(() => {
    if (lib !== "ready") return null;
    try {
      const qr = window.qrcode(0, "M");
      qr.addData(payload, "Byte");
      qr.make();
      const n = qr.getModuleCount();
      let d = "";
      for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) if (qr.isDark(r, c)) d += `M${c} ${r}h1v1h-1z`;
      return { n, d };
    } catch (e) {
      return { error: true };
    }
  }, [lib, payload]);
  const box = { width: `${mm}mm`, height: `${mm}mm` };
  if (lib === "error" || (data && data.error))
    return <div style={{ ...box, border: "0.3mm solid #000", fontSize: "7pt", padding: "2mm", boxSizing: "border-box" }}>QR indisponible : le générateur n'a pas pu se charger.</div>;
  if (!data) return <div style={{ ...box, background: "#eee" }} />;
  const { n, d } = data;
  const u = n / 46;
  const c = n / 2;
  return (
    <svg viewBox={`0 0 ${n} ${n}`} style={{ ...box, display: "block" }} shapeRendering="crispEdges">
      <rect width={n} height={n} fill="#fff" />
      <path d={d} fill="#000" />
      <rect x={c - 3.5 * u} y={c - 3.5 * u} width={7 * u} height={7 * u} fill="#fff" />
      <rect x={c - 3 * u} y={c - 3 * u} width={6 * u} height={6 * u} fill="#000" />
      <rect x={c - 1.875 * u} y={c - 0.5625 * u} width={3.75 * u} height={1.125 * u} fill="#fff" />
      <rect x={c - 0.5625 * u} y={c - 1.875 * u} width={1.125 * u} height={3.75 * u} fill="#fff" />
    </svg>
  );
}

function BlankBox({ w, h }) {
  const b = "0.5mm solid #000";
  const k = { position: "absolute", width: "3mm", height: "3mm" };
  return (
    <div style={{ position: "relative", width: `${w}mm`, height: `${h}mm`, marginTop: "1mm" }}>
      <div style={{ ...k, top: 0, left: 0, borderTop: b, borderLeft: b }} />
      <div style={{ ...k, top: 0, right: 0, borderTop: b, borderRight: b }} />
      <div style={{ ...k, bottom: 0, left: 0, borderBottom: b, borderLeft: b }} />
      <div style={{ ...k, bottom: 0, right: 0, borderBottom: b, borderRight: b }} />
    </div>
  );
}

function QrBillSlip({ qr }) {
  const p = qr.parts;
  const font = "Arial, Helvetica, 'Liberation Sans', sans-serif";
  const R = { l: "6pt", v: "8pt", lh: "9pt", box: [52, 20], amt: [30, 10] };
  const P = { l: "8pt", v: "10pt", lh: "11pt", box: [65, 25], amt: [40, 15] };
  const lab = (s, t) => <div style={{ fontSize: s.l, fontWeight: 700, lineHeight: s.lh, marginTop: "3pt" }}>{t}</div>;
  const val = (s, t) => (t ? <div style={{ fontSize: s.v, lineHeight: s.lh }}>{t}</div> : null);
  const info = (s, full) => (
    <div>
      {lab(s, "Compte / Payable à")}
      {val(s, groupIban(p.iban))}
      {val(s, p.name)}
      {val(s, [p.street, p.no].filter(Boolean).join(" "))}
      {val(s, `${p.zip} ${p.town}`)}
      {p.ref && lab(s, "Référence")}
      {p.ref && val(s, groupQrr(p.ref))}
      {full && lab(s, "Informations supplémentaires")}
      {full && val(s, p.msg)}
      {p.debtor ? lab(s, "Payable par") : lab(s, "Payable par (nom/adresse)")}
      {p.debtor && val(s, p.debtor.name)}
      {p.debtor && val(s, [p.debtor.street, p.debtor.no].filter(Boolean).join(" "))}
      {p.debtor && val(s, `${p.debtor.country !== "CH" ? p.debtor.country + "-" : ""}${p.debtor.zip} ${p.debtor.town}`)}
      {!p.debtor && <BlankBox w={s.box[0]} h={s.box[1]} />}
    </div>
  );
  const amount = (s) => (
    <div style={{ display: "flex", gap: "4mm", paddingTop: "2mm" }}>
      <div>{lab(s, "Monnaie")}{val(s, "CHF")}</div>
      <div>
        {lab(s, "Montant")}
        {p.amount ? val(s, fmtSlipAmount(p.amount)) : <BlankBox w={s.amt[0]} h={s.amt[1]} />}
      </div>
    </div>
  );
  return (
    <div className="qr-slip" style={{ width: "210mm", height: "105mm", display: "flex", boxSizing: "border-box", borderTop: "0.3mm dashed #000", fontFamily: font, color: "#000", background: "#fff", flexShrink: 0 }}>
      <div style={{ width: "62mm", boxSizing: "border-box", padding: "5mm", borderRight: "0.3mm dashed #000", display: "flex", flexDirection: "column" }}>
        <div style={{ fontSize: "11pt", fontWeight: 700, height: "7mm" }}>Récépissé</div>
        <div style={{ height: "56mm" }}>{info(R, false)}</div>
        <div style={{ height: "14mm" }}>{amount(R)}</div>
        <div style={{ marginTop: "auto", textAlign: "right", fontSize: "6pt", fontWeight: 700 }}>Point de dépôt</div>
      </div>
      <div style={{ width: "148mm", boxSizing: "border-box", padding: "5mm", display: "flex" }}>
        <div style={{ width: "51mm" }}>
          <div style={{ fontSize: "11pt", fontWeight: 700, height: "7mm" }}>Section paiement</div>
          <div style={{ height: "56mm", paddingTop: "5mm", boxSizing: "border-box" }}>
            <QrCode payload={qr.payload} mm={46} />
          </div>
          <div style={{ height: "22mm" }}>{amount(P)}</div>
        </div>
        <div style={{ width: "87mm" }}>{info(P, true)}</div>
      </div>
    </div>
  );
}

function InvoiceSheet({ inv }) {
  const co = inv.company;
  const cl = inv.client;
  const qr = useMemo(() => buildSwissQR(inv), [inv]);
  const hasSlip = qr.errors.length === 0;
  return (
    <div className="print-area invoice-sheet mx-auto border shadow-sm" style={{ background: "#fff", borderColor: C.line, width: "210mm", height: "297mm", minHeight: "297mm", maxHeight: "297mm", position: "relative", overflow: "hidden", boxSizing: "border-box" }}>
      <div className="invoice-body" style={{ padding: "10mm 14mm 4mm", color: C.text, height: hasSlip ? "192mm" : "297mm", overflow: "hidden", boxSizing: "border-box" }}>
        <div className="flex justify-between items-start pb-4 border-b-2" style={{ borderColor: C.blue }}>
          <img src={LOGO} alt={co.nom} style={{ height: "62px", width: "auto" }} />
          <div className="text-right text-xs leading-relaxed" style={{ color: C.mute }}>
            <div className="font-semibold text-sm" style={{ color: C.ink }}>{co.nom}</div>
            {co.adresse && <div>{co.adresse}</div>}
            {co.npaLocalite && <div>{co.npaLocalite}</div>}
            {co.telephone && <div>{co.telephone}</div>}
            {co.email && <div>{co.email}</div>}
            {co.ide && <div>{co.ide}</div>}
          </div>
        </div>

        <div className="flex justify-between items-start mt-4 mb-4">
          <div>
            <div className="text-xs uppercase tracking-widest" style={{ color: C.mute, letterSpacing: "0.15em" }}>Facture</div>
            <h1 className="font-display text-2xl mt-1" style={{ color: C.ink }}>N° {inv.number}</h1>
            <div className="text-xs font-mono mt-3 leading-relaxed" style={{ color: C.mute }}>
              <div>Date : {fmtDate(inv.date)}</div>
              <div>Échéance : {fmtDate(inv.due)}</div>
              {(inv.from || inv.to) && <div>Période : {fmtDate(inv.from)} au {fmtDate(inv.to)}</div>}
              <div>Code client : {cl.code}</div>
            </div>
          </div>
          <div className="text-sm leading-relaxed" style={{ minWidth: "220px" }}>
            <div className="font-semibold">{cl.nom}</div>
            {cl.contact && <div>{cl.contact}</div>}
            {cl.adresse && <div>{cl.adresse}</div>}
            {cl.npaLocalite && <div>{cl.npaLocalite}</div>}
          </div>
        </div>

        {inv.groups.map((g) => (
          <div key={g.dossier} className="mb-5">
            <div className="flex items-center gap-2 mb-1 pb-1 border-b" style={{ borderColor: C.line }}>
              <FolderOpen size={13} style={{ color: C.green }} />
              <div className="font-semibold text-sm" style={{ color: C.ink }}>{g.dossier}</div>
            </div>
            <table className="w-full text-sm">
              <tbody>
                {g.items.map((it) => (
                  <tr key={it.id}>
                    <td className="py-1 pr-2 font-mono text-xs align-top" style={{ color: C.mute, width: "78px" }}>{fmtDate(it.date)}</td>
                    <td className="py-1 pr-2 align-top">{it.description || "Prestation"}</td>
                    <td className="py-1 pr-2 font-mono text-right align-top" style={{ width: "64px" }}>{fmtHours(it.hours)} h</td>
                    <td className="py-1 pr-2 font-mono text-right align-top text-xs" style={{ width: "70px", color: C.mute }}>{fmtHours(it.rate)}/h</td>
                    <td className="py-1 font-mono text-right align-top" style={{ width: "92px" }}>{fmtCHF(it.hours * it.rate)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
            <div className="flex justify-end gap-4 mt-1 text-xs font-mono" style={{ color: C.mute }}>
              <span>Sous-total dossier : {fmtHours(g.hours)} h</span>
              <span className="font-semibold" style={{ color: C.ink }}>{fmtCHF(g.amount)}</span>
            </div>
          </div>
        ))}

        <div className="mt-3 pt-2 border-t-2 flex justify-end" style={{ borderColor: C.blue }}>
          <div style={{ width: "290px" }} className="text-sm">
            <div className="flex justify-between py-0.5" style={{ color: C.mute }}>
              <span>Total heures</span><span className="font-mono">{fmtHours(inv.totalHours)} h</span>
            </div>
            <div className="flex justify-between py-0.5">
              <span>Montant HT</span><span className="font-mono">{fmtCHF(inv.subtotal)}</span>
            </div>
            {inv.tvaRate > 0 && (
              <div className="flex justify-between py-0.5">
                <span>TVA {inv.tvaRate}%</span><span className="font-mono">{fmtCHF(inv.tva)}</span>
              </div>
            )}
            {Math.abs(inv.arrondi) > 0.0001 && (
              <div className="flex justify-between py-0.5" style={{ color: C.mute }}>
                <span>Arrondi</span><span className="font-mono">{fmtCHF(inv.arrondi)}</span>
              </div>
            )}
            <div className="flex justify-between text-lg font-semibold pt-2 mt-1 border-t" style={{ color: C.ink, borderColor: C.line }}>
              <span className="font-display">Total à payer</span><span className="font-mono">{fmtCHF(inv.total)}</span>
            </div>
          </div>
        </div>

        <div className="mt-3 pt-2 border-t text-xs leading-relaxed" style={{ borderColor: C.line, color: C.mute }}>
          <div>Paiement à {co.delaiPaiement} jours, soit avant le {fmtDate(inv.due)}.</div>
          {co.iban && <div className="font-mono mt-1" style={{ color: C.text }}>IBAN : {co.iban}</div>}
          {co.piedDePage && <div className="mt-2">{co.piedDePage}</div>}
        </div>
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, bottom: 0 }}>
        {hasSlip ? (
          <QrBillSlip qr={qr} />
        ) : (
          <div className="no-print m-4 p-3 rounded-sm text-xs" style={{ background: "#FBF1E4", color: "#7A4B12", border: "1px solid #EBCB9A" }}>
            <div className="font-semibold mb-1">QR-facture non générée : informations à compléter</div>
            {qr.errors.map((m) => (<div key={m}>• {m}</div>))}
          </div>
        )}
      </div>
    </div>
  );
}

function DriveFiles({ clients }) {
  const [status, setStatus] = useState(null);
  const [files, setFiles] = useState([]);
  const [folderId, setFolderId] = useState("");
  const [rootId, setRootId] = useState("");
  const [stack, setStack] = useState([]);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [folderName, setFolderName] = useState("");

  const load = async (id) => {
    setBusy(true);
    setError("");
    try {
      const st = await window.scApi("/api/drive/status");
      setStatus(st);
      if (!st.connected) return;
      const data = await window.scApi("/api/drive/files" + (id ? `?folderId=${encodeURIComponent(id)}` : ""));
      setFiles(data.files || []);
      setFolderId(data.parentId || "");
      setRootId(data.rootId || "");
    } catch (err) {
      setError(err.message || "No se pudo leer Drive");
    } finally {
      setBusy(false);
    }
  };

  useEffect(() => { load(""); }, []);

  const openFolder = (f) => {
    setStack((s) => [...s, { id: folderId, name: f.name }]);
    load(f.id);
  };
  const up = () => {
    const next = stack.slice(0, -1);
    const parent = next.length ? next[next.length - 1].id : "";
    setStack(next);
    load(parent);
  };
  const onUpload = async (e) => {
    const file = e.target.files && e.target.files[0];
    e.target.value = "";
    if (!file) return;
    const body = new FormData();
    body.append("file", file);
    if (folderId) body.append("parentId", folderId);
    setBusy(true);
    setError("");
    try {
      await window.scApi("/api/drive/upload", { method: "POST", body });
      await load(folderId);
    } catch (err) {
      setError(err.message || "No se pudo subir");
      setBusy(false);
    }
  };
  const makeFolder = async (name) => {
    const n = String(name || "").trim();
    if (!n) return;
    setBusy(true);
    setError("");
    try {
      await window.scApi("/api/drive/folder", { method: "POST", body: JSON.stringify({ name: n, parentId: folderId }) });
      setFolderName("");
      await load(folderId);
    } catch (err) {
      setError(err.message || "No se pudo crear la carpeta");
      setBusy(false);
    }
  };

  if (!status) return <div className="text-sm" style={{ color: C.mute }}>Chargement de Google Drive…</div>;
  if (!status.connected) {
    return (
      <Card className="p-5 max-w-2xl">
        <h2 className="font-display text-xl mb-2" style={{ color: C.ink }}>Fichiers Google Drive</h2>
        <p className="text-sm mb-3" style={{ color: C.mute }}>
          Drive no está conectado todavía. Cuando lo configure en Render, los archivos del despacho aparecerán aquí, en el PC y en el móvil.
        </p>
        {status.error && <div className="text-sm mb-2" style={{ color: "#9B2C2C" }}>{status.error}</div>}
        <ol className="text-sm space-y-1" style={{ color: C.text }}>
          <li>1. Cree una carpeta en Google Drive, por ejemplo «A-Fid».</li>
          <li>2. En Google Cloud, cree una cuenta de servicio y descargue la clave JSON.</li>
          <li>3. Comparta esa carpeta con el email de la cuenta de servicio, como Editor.</li>
          <li>4. En Render, variable <span className="font-mono">GOOGLE_SERVICE_ACCOUNT_JSON</span> = el contenido del JSON.</li>
          <li>5. Variable <span className="font-mono">DRIVE_FOLDER_ID</span> = el id de la carpeta (está en la URL de Drive).</li>
        </ol>
      </Card>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h2 className="font-display text-xl" style={{ color: C.ink }}>Fichiers</h2>
          <div className="text-xs" style={{ color: C.mute }}>{status.email}</div>
        </div>
        <label className="flex items-center gap-2 rounded-sm px-3 py-2 text-sm cursor-pointer" style={{ background: C.ink, color: "#fff" }}>
          <Upload size={14} /> Ajouter un fichier
          <input type="file" className="hidden" onChange={onUpload} />
        </label>
      </div>
      {error && <div className="text-sm" style={{ color: "#9B2C2C" }}>{error}</div>}
      <Card className="p-4">
        <div className="flex flex-wrap gap-2 mb-3">
          {stack.length > 0 && <Btn kind="secondary" onClick={up}>Dossier parent</Btn>}
          <Input className="max-w-xs" placeholder="Nouveau dossier" value={folderName} onChange={(e) => setFolderName(e.target.value)} />
          <Btn kind="secondary" onClick={() => makeFolder(folderName)} disabled={busy}>Créer</Btn>
          <Select className="max-w-xs" value="" onChange={(e) => e.target.value && makeFolder(e.target.value)}>
            <option value="">Dossier client…</option>
            {clients.map((c) => <option key={c.id || c.code} value={`${c.code} ${c.nom}`}>{c.code} — {c.nom}</option>)}
          </Select>
        </div>
        {busy && <div className="text-xs mb-2" style={{ color: C.mute }}>Chargement…</div>}
        <div className="divide-y" style={{ borderColor: C.line }}>
          {files.length === 0 && <div className="text-sm py-4" style={{ color: C.mute }}>Aucun fichier dans ce dossier.</div>}
          {files.map((f) => {
            const isFolder = f.mimeType === "application/vnd.google-apps.folder";
            return (
              <div key={f.id} className="flex items-center justify-between gap-3 py-2">
                <button className="text-left text-sm" style={{ color: C.ink }} onClick={() => isFolder && openFolder(f)}>
                  {isFolder ? "📁" : "📄"} {f.name}
                </button>
                {!isFolder && f.webViewLink && (
                  <a href={f.webViewLink} target="_blank" rel="noreferrer" className="text-xs flex items-center gap-1" style={{ color: C.blue }}>
                    <ExternalLink size={12} /> Ouvrir
                  </a>
                )}
              </div>
            );
          })}
        </div>
        {rootId && stack.length === 0 && <div className="text-xs mt-3 font-mono" style={{ color: C.mute }}>Dossier racine {rootId}</div>}
      </Card>
    </div>
  );
}

function currentSession() {
  try { return JSON.parse(localStorage.getItem("sc-user") || "null"); } catch { return null; }
}

function logout() {
  localStorage.removeItem("sc-token");
  localStorage.removeItem("sc-user");
  window.location.reload();
}

function SessionBar() {
  const me = currentSession();
  if (!me) return null;
  return (
    <div className="text-xs mt-1 flex items-center justify-end gap-2">
      {me.sandbox && <span className="px-1.5 py-0.5 rounded-sm font-semibold" style={{ background: "#FBF1E4", color: "#7A4B12" }}>PRUEBA</span>}
      <span style={{ color: C.mute }}>{me.username}</span>
      <button type="button" className="underline" style={{ color: C.blue }} onClick={logout}>Salir</button>
    </div>
  );
}

function UsersPanel() {
  const me = currentSession();
  const [users, setUsers] = useState([]);
  const [form, setForm] = useState({ username: "", name: "", password: "", sandbox: false });
  const [error, setError] = useState("");
  const [ownPassword, setOwnPassword] = useState("");

  const load = async () => {
    if (!me || me.role !== "admin") return;
    const data = await window.scApi("/api/users");
    setUsers(data.users || []);
  };
  useEffect(() => { load().catch(() => {}); }, []);
  if (!me) return null;

  const create = async () => {
    setError("");
    try {
      await window.scApi("/api/users", { method: "POST", body: JSON.stringify(form) });
      setForm({ username: "", name: "", password: "", sandbox: false });
      await load();
    } catch (err) {
      setError(err.message || "No se pudo crear");
    }
  };
  const remove = async (id) => {
    if (!window.confirm("¿Borrar este usuario?")) return;
    await window.scApi("/api/users/" + id, { method: "DELETE" });
    await load();
  };
  const changeOwn = async () => {
    setError("");
    try {
      await window.scApi("/api/password", { method: "POST", body: JSON.stringify({ password: ownPassword }) });
      setOwnPassword("");
      setError("Contraseña cambiada");
    } catch (err) {
      setError(err.message || "No se pudo cambiar");
    }
  };

  return (
    <Card className="p-5 mt-4">
      <h3 className="font-display text-lg mb-2" style={{ color: C.ink }}>Usuarios</h3>
      <p className="text-xs mb-3" style={{ color: C.mute }}>
        Los usuarios normales ven los mismos clientes. Si marca «solo prueba», ese acceso tiene clientes y facturas aparte.
      </p>
      {me.sandbox && <div className="text-xs mb-3" style={{ color: "#7A4B12" }}>Está en la cuenta de prueba. Lo que haga aquí no aparece en la cuenta real.</div>}
      <div className="flex gap-2 mb-3">
        <Input type="password" placeholder="Nueva contraseña de esta cuenta" value={ownPassword} onChange={(e) => setOwnPassword(e.target.value)} />
        <Btn kind="secondary" onClick={changeOwn}>Cambiar</Btn>
      </div>
      {me.role === "admin" && (
        <>
          <div className="space-y-1 mb-3 text-sm">
            {users.map((u) => (
              <div key={u.id} className="flex items-center justify-between gap-2">
                <span>{u.username} — {u.name} {u.sandbox ? "(prueba)" : ""} {u.role === "admin" ? "(admin)" : ""}</span>
                {u.role !== "admin" && <button className="text-xs underline" style={{ color: C.danger }} onClick={() => remove(u.id)}>Borrar</button>}
              </div>
            ))}
          </div>
          <div className="grid sm:grid-cols-2 gap-2">
            <Input placeholder="usuario" value={form.username} onChange={(e) => setForm({ ...form, username: e.target.value })} />
            <Input placeholder="nombre" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />
            <Input type="password" placeholder="contraseña" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} />
            <label className="text-xs flex items-center gap-2"><input type="checkbox" checked={form.sandbox} onChange={(e) => setForm({ ...form, sandbox: e.target.checked })} /> solo prueba</label>
          </div>
          <Btn className="mt-2" onClick={create}>Añadir usuario</Btn>
        </>
      )}
      {error && <div className="text-xs mt-2" style={{ color: "#7A4B12" }}>{error}</div>}
    </Card>
  );
}

export default function App() {
  const [loaded, setLoaded] = useState(false);
  const [entries, setEntries] = useState([]);
  const [clients, setClients] = useState([]);
  const [company, setCompany] = useState(defaultCompany);
  const [invoices, setInvoices] = useState([]);

  const [tab, setTab] = useState("saisie");

  const [form, setForm] = useState({ date: todayISO(), clientCode: "", dossier: "", description: "", hours: "", rate: "150" });
  const [filterClient, setFilterClient] = useState("");
  const [search, setSearch] = useState("");

  const [timer, setTimer] = useState(null); // { startTs, clientCode, dossier, description }
  const [tClient, setTClient] = useState("");
  const [tDossier, setTDossier] = useState("");
  const [tDesc, setTDesc] = useState("");
  const [tick, setTick] = useState(Date.now());

  const [clientForm, setClientForm] = useState(emptyClient);
  const [clientError, setClientError] = useState("");

  const [invClient, setInvClient] = useState("");
  const [invNumber, setInvNumber] = useState("");
  const [invDate, setInvDate] = useState(todayISO());
  const [dateFrom, setDateFrom] = useState("");
  const [dateTo, setDateTo] = useState("");
  const [includeInvoiced, setIncludeInvoiced] = useState(false);
  const [tvaRate, setTvaRate] = useState(null);
  const [invoiceView, setInvoiceView] = useState(null);

  const TIMER_SESSION = "sc-timer-session";
  const readSessionTimer = () => {
    try {
      const raw = sessionStorage.getItem(TIMER_SESSION);
      return raw ? JSON.parse(raw) : null;
    } catch {
      return null;
    }
  };
  const writeSessionTimer = (value) => {
    try {
      if (value) sessionStorage.setItem(TIMER_SESSION, JSON.stringify(value));
      else sessionStorage.removeItem(TIMER_SESSION);
    } catch {}
  };

  useEffect(() => {
    (async () => {
      const [e, c, co, iv] = await Promise.all([
        load(KEYS.entries, []),
        load(KEYS.clients, []),
        load(KEYS.company, defaultCompany),
        load(KEYS.invoices, []),
      ]);
      setEntries(e);
      setClients(c);
      setCompany({ ...defaultCompany, ...co });
      setInvoices(iv);
      const local = readSessionTimer();
      if (local && local.startTs) {
        setTimer(local);
        setTClient(local.clientCode);
        setTDossier(local.dossier);
        setTDesc(local.description || "");
      }
      save(KEYS.timer, null);
      setLoaded(true);
    })();
  }, []);

  useEffect(() => {
    window.stopTimerForClose = () => writeSessionTimer(null);
    const onHide = (e) => {
      if (!e.persisted) writeSessionTimer(null);
    };
    window.addEventListener("pagehide", onHide);
    return () => window.removeEventListener("pagehide", onHide);
  }, []);

  useEffect(() => { if (loaded) save(KEYS.entries, entries); }, [entries, loaded]);
  useEffect(() => { if (loaded) save(KEYS.clients, clients); }, [clients, loaded]);
  useEffect(() => { if (loaded) save(KEYS.company, company); }, [company, loaded]);
  useEffect(() => { if (loaded) save(KEYS.invoices, invoices); }, [invoices, loaded]);
  useEffect(() => { writeSessionTimer(timer); }, [timer]);

  useEffect(() => {
    if (!timer) return;
    const id = setInterval(() => setTick(Date.now()), 1000);
    return () => clearInterval(id);
  }, [timer]);

  // ---------- Clients ----------
  const allCodes = useMemo(() => {
    const map = new Map();
    clients.forEach((c) => map.set(c.code, c.nom));
    entries.forEach((e) => { if (!map.has(e.clientCode)) map.set(e.clientCode, e.clientName || e.clientCode); });
    return Array.from(map.entries()).sort((a, b) => a[0].localeCompare(b[0]));
  }, [clients, entries]);

  const nameOf = (code) => (allCodes.find(([c]) => c === code) || [code, code])[1];
  const clientByCode = (code) => clients.find((c) => c.code === code);

  const saveClient = () => {
    const code = clientForm.code.trim().toUpperCase();
    const nom = clientForm.nom.trim();
    if (!code || !nom) { setClientError("Le code client et le nom sont obligatoires."); return; }
    if (clients.some((c) => c.code === code && c.id !== clientForm.id)) {
      setClientError("Ce code client existe déjà. Choisissez-en un autre.");
      return;
    }
    setClientError("");
    if (clientForm.id) {
      const old = clients.find((c) => c.id === clientForm.id);
      setClients(clients.map((c) => (c.id === clientForm.id ? { ...clientForm, code, nom } : c)));
      if (old && old.code !== code) {
        setEntries(entries.map((e) => (e.clientCode === old.code ? { ...e, clientCode: code } : e)));
      }
    } else {
      setClients([...clients, { ...clientForm, id: uid(), code, nom }]);
    }
    setClientForm(emptyClient);
  };

  const deleteClient = (c) => {
    if (entries.some((e) => e.clientCode === c.code)) return;
    setClients(clients.filter((x) => x.id !== c.id));
    if (clientForm.id === c.id) setClientForm(emptyClient);
  };

  const clientStats = (code) => {
    const mine = entries.filter((e) => e.clientCode === code);
    const hours = mine.reduce((s, e) => s + e.hours, 0);
    const pending = mine.filter((e) => !e.invoiceId).reduce((s, e) => s + e.hours * e.rate, 0);
    return { count: mine.length, hours, pending };
  };

  // ---------- Saisie ----------
  const pickClientForEntry = (code) => {
    const c = clientByCode(code);
    setForm({ ...form, clientCode: code, rate: c ? String(c.taux) : form.rate });
  };

  const addEntry = () => {
    if (!form.clientCode || !form.dossier.trim() || num(form.hours) <= 0) return;
    setEntries([
      {
        id: uid(),
        date: form.date,
        clientCode: form.clientCode,
        clientName: nameOf(form.clientCode),
        dossier: form.dossier.trim(),
        description: form.description.trim(),
        hours: num(form.hours),
        rate: num(form.rate),
      },
      ...entries,
    ]);
    setForm({ ...form, description: "", hours: "" });
  };

  const deleteEntry = (id) => setEntries(entries.filter((e) => e.id !== id));

  const dossiersFor = (code) => Array.from(new Set(entries.filter((e) => e.clientCode === code).map((e) => e.dossier)));
  const dossiersOfClient = useMemo(() => dossiersFor(form.clientCode), [entries, form.clientCode]);
  const dossiersOfTimerClient = useMemo(() => dossiersFor(tClient), [entries, tClient]);

  const pickTimerClient = (code) => { setTClient(code); setTDossier(""); };

  const startTimer = () => {
    if (!tClient || !tDossier.trim() || timer) return;
    const next = { startTs: Date.now(), clientCode: tClient, dossier: tDossier.trim(), description: tDesc.trim() };
    setTimer(next);
    writeSessionTimer(next);
  };

  const stopTimer = () => {
    if (!timer) return;
    const endTs = Date.now();
    const hours = Math.round((Math.max(0, endTs - timer.startTs) / 3600000) * 100) / 100;
    if (hours > 0) {
      const c = clientByCode(timer.clientCode);
      setEntries([
        {
          id: uid(),
          date: localDateISO(timer.startTs),
          clientCode: timer.clientCode,
          clientName: nameOf(timer.clientCode),
          dossier: timer.dossier,
          description: timer.description,
          hours,
          rate: c ? num(c.taux) : 150,
          startTime: localHM(timer.startTs),
          endTime: localHM(endTs),
        },
        ...entries,
      ]);
    }
    setTimer(null);
    setTDesc("");
    writeSessionTimer(null);
    save(KEYS.timer, null);
  };

  const filteredEntries = useMemo(() => {
    const s = search.trim().toLowerCase();
    return entries
      .filter((e) => (filterClient ? e.clientCode === filterClient : true))
      .filter((e) => !s || e.dossier.toLowerCase().includes(s) || (e.description || "").toLowerCase().includes(s) || e.clientCode.toLowerCase().includes(s))
      .sort((a, b) => (a.date < b.date ? 1 : -1));
  }, [entries, filterClient, search]);

  const totalHoursAll = filteredEntries.reduce((s, e) => s + e.hours, 0);
  const totalAmountAll = filteredEntries.reduce((s, e) => s + e.hours * e.rate, 0);

  // ---------- Facturation ----------
  const invoiceEntries = useMemo(() => {
    if (!invClient) return [];
    return entries
      .filter((e) => e.clientCode === invClient)
      .filter((e) => includeInvoiced || !e.invoiceId)
      .filter((e) => (dateFrom ? e.date >= dateFrom : true))
      .filter((e) => (dateTo ? e.date <= dateTo : true))
      .sort((a, b) => (a.date < b.date ? -1 : 1));
  }, [entries, invClient, includeInvoiced, dateFrom, dateTo]);

  const suggestedNumber = useMemo(() => {
    const year = (invDate || todayISO()).slice(0, 4);
    const max = invoices
      .filter((i) => i.number.startsWith(year + "-"))
      .reduce((m, i) => Math.max(m, parseInt(i.number.split("-")[1], 10) || 0), 0);
    return `${year}-${String(max + 1).padStart(3, "0")}`;
  }, [invoices, invDate]);

  const effectiveTva = tvaRate === null ? company.tvaRate : tvaRate;

  const buildInvoice = () => {
    const map = new Map();
    invoiceEntries.forEach((e) => {
      if (!map.has(e.dossier)) map.set(e.dossier, []);
      map.get(e.dossier).push({ id: e.id, date: e.date, description: e.description, hours: e.hours, rate: e.rate });
    });
    const groups = Array.from(map.entries()).map(([dossier, items]) => ({
      dossier,
      items,
      hours: items.reduce((s, i) => s + i.hours, 0),
      amount: items.reduce((s, i) => s + i.hours * i.rate, 0),
    }));
    const subtotal = groups.reduce((s, g) => s + g.amount, 0);
    const rate = num(effectiveTva);
    const tva = (subtotal * rate) / 100;
    const raw = subtotal + tva;
    const total = Math.round(raw * 20) / 20;
    const c = clientByCode(invClient) || { code: invClient, nom: nameOf(invClient) };
    return {
      id: uid(),
      number: invNumber.trim() || suggestedNumber,
      date: invDate,
      due: addDays(invDate, parseInt(company.delaiPaiement, 10) || 30),
      from: dateFrom,
      to: dateTo,
      client: { code: c.code, nom: c.nom, contact: c.contact || "", adresse: c.adresse || "", npaLocalite: c.npaLocalite || "", email: c.email || "", pays: c.pays || "CH" },
      company: { ...company },
      groups,
      totalHours: groups.reduce((s, g) => s + g.hours, 0),
      subtotal,
      tvaRate: rate,
      tva,
      arrondi: total - raw,
      total,
      entryIds: invoiceEntries.map((e) => e.id),
      saved: false,
    };
  };

  const saveInvoice = () => {
    const inv = { ...invoiceView, saved: true };
    setInvoices([inv, ...invoices]);
    setEntries(entries.map((e) => (inv.entryIds.includes(e.id) ? { ...e, invoiceId: inv.id } : e)));
    setInvoiceView(inv);
    setInvNumber("");
  };

  const deleteInvoice = (inv) => {
    setInvoices(invoices.filter((i) => i.id !== inv.id));
    setEntries(entries.map((e) => (e.invoiceId === inv.id ? { ...e, invoiceId: undefined } : e)));
  };

  const invoiceNumberOf = (id) => (invoices.find((i) => i.id === id) || {}).number;

  const qrCheck = useMemo(() => buildSwissQR({ company, client: {}, number: "2026-001", total: 0 }), [company]);

  const tabs = [
    ["saisie", "Saisie du temps", Clock],
    ["clients", "Clients", Users],
    ["facturation", "Facturation", FileText],
    ["entreprise", "Mon entreprise", Building2],
    ["fichiers", "Fichiers", FolderOpen],
  ];

  return (
    <div className="min-h-screen print-root" style={{ background: C.paper, fontFamily: "'Inter', ui-sans-serif, system-ui", color: C.text }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap');
        .font-display { font-family: 'Fraunces', serif; }
        .font-mono { font-family: 'IBM Plex Mono', monospace; }
        .tab-underline { position: relative; }
        .tab-underline.active::after { content: ''; position: absolute; left: 0; right: 0; bottom: -1px; height: 2px; background: ${C.blue}; }
        input:focus, select:focus, textarea:focus { outline: none; box-shadow: 0 0 0 2px rgba(31,95,174,0.25); }
        @page { size: A4; margin: 0; }
        @media print {
          .no-print { display: none !important; }
          .print-area { box-shadow: none !important; border: none !important; margin: 0 !important; width: 210mm !important; height: 297mm !important; max-height: 297mm !important; overflow: hidden !important; page-break-after: avoid !important; break-after: avoid !important; }
          .invoice-sheet, .qr-slip { page-break-inside: avoid !important; break-inside: avoid !important; }
          .print-reset { padding: 0 !important; max-width: none !important; margin: 0 !important; height: 297mm !important; overflow: hidden !important; }
          .print-root { min-height: 0 !important; height: 297mm !important; background: white !important; overflow: hidden !important; }
          .sheet-wrap { overflow: hidden !important; height: 297mm !important; }
          html, body { margin: 0 !important; padding: 0 !important; background: white !important; height: 297mm !important; overflow: hidden !important; }
        }
      `}</style>

      <div className="no-print border-b" style={{ borderColor: C.line }}>
        <div className="max-w-5xl mx-auto px-5 pt-5">
          <div className="flex items-center justify-between mb-4 gap-4">
            <img src={LOGO} alt="A-Fid Comptabilité" style={{ height: "44px", width: "auto" }} />
            <div className="text-right">
              <div className="font-display text-xl" style={{ color: C.ink }}>Temps &amp; facturation</div>
              <div className="text-xs font-mono" style={{ color: C.mute }}>{loaded ? "Enregistré automatiquement" : "Chargement…"}</div>
              <SessionBar />
            </div>
          </div>
          <div className="flex gap-5 text-sm font-medium overflow-x-auto">
            {tabs.map(([id, label, Icon]) => (
              <button
                key={id}
                className={`tab-underline pb-3 flex items-center gap-1.5 whitespace-nowrap ${tab === id ? "active" : ""}`}
                style={{ color: tab === id ? C.ink : C.mute }}
                onClick={() => { setTab(id); setInvoiceView(null); }}
              >
                <Icon size={14} /> {label}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="max-w-5xl mx-auto px-5 py-6 print-reset">
        {/* ---------------- SAISIE ---------------- */}
        {tab === "saisie" && (
          <div className="grid md:grid-cols-5 gap-5">
            <div className="md:col-span-2 space-y-5">
              <Card className="p-5" style={timer ? { borderColor: C.green } : undefined}>
                <div className="flex items-center gap-2 mb-4">
                  <Clock size={16} style={{ color: timer ? C.green : C.blue }} />
                  <h2 className="font-display text-lg" style={{ color: C.ink }}>Chronomètre</h2>
                  {timer && (
                    <span className="ml-auto text-xs px-2 py-0.5 rounded-sm font-mono" style={{ background: C.soft, color: C.green }}>
                      En cours
                    </span>
                  )}
                </div>
                {allCodes.length === 0 ? (
                  <div className="text-sm" style={{ color: C.mute }}>Créez d'abord une fiche client pour pouvoir démarrer le chronomètre.</div>
                ) : timer ? (
                  <div className="space-y-3">
                    <div className="text-center py-3 rounded-sm" style={{ background: C.paper }}>
                      <div className="font-mono text-3xl tabular-nums" style={{ color: C.ink }}>{fmtHMS(tick - timer.startTs)}</div>
                      <div className="text-xs mt-1" style={{ color: C.mute }}>Démarré à {localHM(timer.startTs)}</div>
                    </div>
                    <div className="flex items-center gap-2 flex-wrap text-sm">
                      <span className="text-xs font-mono font-semibold px-1.5 py-0.5 rounded-sm" style={{ background: C.soft, color: C.ink }}>{timer.clientCode}</span>
                      <span className="font-medium">{timer.dossier}</span>
                    </div>
                    <Field label="Description (facultatif)">
                      <Input placeholder="Ce sur quoi vous travaillez…" value={tDesc} onChange={(e) => setTDesc(e.target.value)} />
                    </Field>
                    <Btn onClick={stopTimer} className="w-full" kind="secondary" style={{ borderColor: C.danger, color: C.danger }}>
                      <Square size={15} /> Arrêter et enregistrer
                    </Btn>
                  </div>
                ) : (
                  <div className="space-y-3">
                    <Field label="Client">
                      <Select className="font-mono" value={tClient} onChange={(e) => pickTimerClient(e.target.value)}>
                        <option value="">Choisir…</option>
                        {allCodes.map(([code, name]) => (<option key={code} value={code}>{code} — {name}</option>))}
                      </Select>
                    </Field>
                    <Field label="Dossier">
                      <Input list="dossiers-timer" placeholder="ex. Bouclement 2025" value={tDossier} onChange={(e) => setTDossier(e.target.value)} />
                      <datalist id="dossiers-timer">{dossiersOfTimerClient.map((d) => (<option key={d} value={d} />))}</datalist>
                    </Field>
                    <Btn onClick={startTimer} disabled={!tClient || !tDossier.trim()} className="w-full">
                      <Play size={15} /> Démarrer
                    </Btn>
                  </div>
                )}
              </Card>

              <Card className="p-5">
                <div className="flex items-center gap-2 mb-4">
                  <Clock size={16} style={{ color: C.green }} />
                  <h2 className="font-display text-lg" style={{ color: C.ink }}>Nouvelle entrée manuelle</h2>
                </div>
                {allCodes.length === 0 ? (
                  <div className="text-sm" style={{ color: C.mute }}>
                    Aucun client pour le moment.{" "}
                    <button className="underline" style={{ color: C.blue }} onClick={() => setTab("clients")}>Créez une fiche client</button>{" "}
                    pour commencer à saisir des heures.
                  </div>
                ) : (
                  <div className="space-y-3">
                    <div className="grid grid-cols-2 gap-3">
                      <Field label="Date"><Input type="date" className="font-mono" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} /></Field>
                      <Field label="Client">
                        <Select className="font-mono" value={form.clientCode} onChange={(e) => pickClientForEntry(e.target.value)}>
                          <option value="">Choisir…</option>
                          {allCodes.map(([code, name]) => (<option key={code} value={code}>{code} — {name}</option>))}
                        </Select>
                      </Field>
                    </div>
                    <Field label="Dossier">
                      <Input list="dossiers" placeholder="ex. Bouclement 2025" value={form.dossier} onChange={(e) => setForm({ ...form, dossier: e.target.value })} />
                      <datalist id="dossiers">{dossiersOfClient.map((d) => (<option key={d} value={d} />))}</datalist>
                    </Field>
                    <Field label="Description">
                      <textarea rows={2} placeholder="Nature de la prestation…" value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} className="w-full border rounded-sm px-2 py-1.5 text-sm resize-none" style={{ borderColor: C.line }} />
                    </Field>
                    <div className="grid grid-cols-2 gap-3">
                      <Field label="Heures"><Input inputMode="decimal" className="font-mono" placeholder="1.50" value={form.hours} onChange={(e) => setForm({ ...form, hours: e.target.value })} /></Field>
                      <Field label="Taux (CHF/h)"><Input inputMode="decimal" className="font-mono" value={form.rate} onChange={(e) => setForm({ ...form, rate: e.target.value })} /></Field>
                    </div>
                    <Btn onClick={addEntry} disabled={!form.clientCode || !form.dossier.trim() || num(form.hours) <= 0} className="w-full">
                      <Plus size={15} /> Ajouter l'entrée
                    </Btn>
                  </div>
                )}
              </Card>
            </div>

            <div className="md:col-span-3">
              <Card>
                <div className="p-4 border-b flex flex-col sm:flex-row gap-2 sm:items-center sm:justify-between" style={{ borderColor: C.line }}>
                  <input type="text" placeholder="Rechercher un dossier…" value={search} onChange={(e) => setSearch(e.target.value)} className="text-sm border-b bg-transparent py-1" style={{ borderColor: C.line, minWidth: "180px" }} />
                  <select value={filterClient} onChange={(e) => setFilterClient(e.target.value)} className="text-sm border rounded-sm px-2 py-1.5 font-mono" style={{ borderColor: C.line }}>
                    <option value="">Tous les clients</option>
                    {allCodes.map(([code, name]) => (<option key={code} value={code}>{code} — {name}</option>))}
                  </select>
                </div>
                <div className="overflow-y-auto" style={{ maxHeight: "520px" }}>
                  {filteredEntries.length === 0 && (
                    <div className="p-8 text-center text-sm" style={{ color: C.mute }}>Aucune entrée. Ajoutez votre premier temps à gauche.</div>
                  )}
                  {filteredEntries.map((e) => (
                    <div key={e.id} className="px-4 py-3 border-b flex items-start gap-3 group" style={{ borderColor: "#EFEDE6" }}>
                      <div className="shrink-0 font-mono text-xs pt-0.5" style={{ color: C.mute, width: "72px" }}>{fmtDate(e.date)}</div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 flex-wrap">
                          <span className="text-xs font-mono font-semibold px-1.5 py-0.5 rounded-sm" style={{ background: C.soft, color: C.ink }}>{e.clientCode}</span>
                          <span className="text-sm font-medium">{e.dossier}</span>
                          {e.invoiceId && (
                            <span className="text-xs px-1.5 py-0.5 rounded-sm" style={{ background: "#E3EEF9", color: C.blue }}>Facturé {invoiceNumberOf(e.invoiceId) || ""}</span>
                          )}
                        </div>
                        {e.description && <div className="text-xs mt-0.5" style={{ color: C.mute }}>{e.description}</div>}
                        {e.startTime && e.endTime && (
                          <div className="text-xs mt-0.5 font-mono" style={{ color: C.mute }}>{e.startTime} – {e.endTime} (chronomètre)</div>
                        )}
                      </div>
                      <div className="text-right shrink-0">
                        <div className="font-mono text-sm" style={{ color: C.ink }}>{fmtHours(e.hours)} h</div>
                        <div className="font-mono text-xs" style={{ color: C.mute }}>{fmtCHF(e.hours * e.rate)}</div>
                      </div>
                      <button onClick={() => deleteEntry(e.id)} className="opacity-0 group-hover:opacity-100 transition-opacity pt-0.5" title="Supprimer">
                        <Trash2 size={14} style={{ color: C.danger }} />
                      </button>
                    </div>
                  ))}
                </div>
                {filteredEntries.length > 0 && (
                  <div className="px-4 py-3 flex justify-between text-sm font-medium" style={{ background: C.paper }}>
                    <span style={{ color: C.mute }}>Total ({filteredEntries.length})</span>
                    <div className="flex gap-4 font-mono" style={{ color: C.ink }}>
                      <span>{fmtHours(totalHoursAll)} h</span><span>{fmtCHF(totalAmountAll)}</span>
                    </div>
                  </div>
                )}
              </Card>
            </div>
          </div>
        )}

        {/* ---------------- CLIENTS ---------------- */}
        {tab === "clients" && (
          <div className="grid md:grid-cols-5 gap-5">
            <div className="md:col-span-2">
              <Card className="p-5">
                <div className="flex items-center gap-2 mb-4">
                  <Users size={16} style={{ color: C.green }} />
                  <h2 className="font-display text-lg" style={{ color: C.ink }}>{clientForm.id ? "Modifier la fiche" : "Nouvelle fiche client"}</h2>
                </div>
                <div className="space-y-3">
                  <div className="grid grid-cols-3 gap-3">
                    <Field label="Code client"><Input className="font-mono uppercase" placeholder="DUP001" value={clientForm.code} onChange={(e) => setClientForm({ ...clientForm, code: e.target.value })} /></Field>
                    <Field label="Nom / raison sociale" className="col-span-2"><Input placeholder="Dupont SA" value={clientForm.nom} onChange={(e) => setClientForm({ ...clientForm, nom: e.target.value })} /></Field>
                  </div>
                  <Field label="Personne de contact"><Input value={clientForm.contact} onChange={(e) => setClientForm({ ...clientForm, contact: e.target.value })} /></Field>
                  <Field label="Adresse"><Input value={clientForm.adresse} onChange={(e) => setClientForm({ ...clientForm, adresse: e.target.value })} /></Field>
                  <div className="grid grid-cols-3 gap-3">
                    <Field label="NPA et localité" className="col-span-2"><Input placeholder="2800 Delémont" value={clientForm.npaLocalite} onChange={(e) => setClientForm({ ...clientForm, npaLocalite: e.target.value })} /></Field>
                    <Field label="Pays (code)"><Input className="font-mono uppercase" maxLength={2} value={clientForm.pays || "CH"} onChange={(e) => setClientForm({ ...clientForm, pays: e.target.value })} /></Field>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <Field label="E-mail"><Input type="email" value={clientForm.email} onChange={(e) => setClientForm({ ...clientForm, email: e.target.value })} /></Field>
                    <Field label="Téléphone"><Input value={clientForm.telephone} onChange={(e) => setClientForm({ ...clientForm, telephone: e.target.value })} /></Field>
                  </div>
                  <Field label="Taux horaire par défaut (CHF/h)"><Input inputMode="decimal" className="font-mono" value={clientForm.taux} onChange={(e) => setClientForm({ ...clientForm, taux: e.target.value })} /></Field>
                  <Field label="Notes">
                    <textarea rows={2} value={clientForm.notes} onChange={(e) => setClientForm({ ...clientForm, notes: e.target.value })} className="w-full border rounded-sm px-2 py-1.5 text-sm resize-none" style={{ borderColor: C.line }} />
                  </Field>
                  {clientError && <div className="text-xs" style={{ color: C.danger }}>{clientError}</div>}
                  <div className="flex gap-2">
                    <Btn onClick={saveClient} className="flex-1"><Save size={15} /> {clientForm.id ? "Enregistrer" : "Créer la fiche"}</Btn>
                    {clientForm.id && <Btn kind="secondary" onClick={() => { setClientForm(emptyClient); setClientError(""); }}>Annuler</Btn>}
                  </div>
                </div>
              </Card>
            </div>

            <div className="md:col-span-3 space-y-3">
              {clients.length === 0 && (
                <Card className="p-8 text-center text-sm"><span style={{ color: C.mute }}>Aucune fiche client. Créez la première à gauche.</span></Card>
              )}
              {[...clients].sort((a, b) => a.code.localeCompare(b.code)).map((c) => {
                const st = clientStats(c.code);
                return (
                  <Card key={c.id} className="p-4">
                    <div className="flex items-start justify-between gap-3">
                      <div className="min-w-0">
                        <div className="flex items-center gap-2 flex-wrap">
                          <span className="text-xs font-mono font-semibold px-1.5 py-0.5 rounded-sm" style={{ background: C.soft, color: C.ink }}>{c.code}</span>
                          <span className="font-medium">{c.nom}</span>
                        </div>
                        <div className="text-xs mt-1.5 leading-relaxed" style={{ color: C.mute }}>
                          {c.contact && <div>{c.contact}</div>}
                          {(c.adresse || c.npaLocalite) && <div>{[c.adresse, c.npaLocalite].filter(Boolean).join(", ")}</div>}
                          {(c.email || c.telephone) && <div>{[c.email, c.telephone].filter(Boolean).join(" · ")}</div>}
                          {c.notes && <div className="mt-1 italic">{c.notes}</div>}
                        </div>
                      </div>
                      <div className="flex gap-1 shrink-0">
                        <button title="Modifier" onClick={() => { setClientForm(c); setClientError(""); }} className="p-1"><Pencil size={14} style={{ color: C.blue }} /></button>
                        <button
                          title={st.count > 0 ? "Suppression impossible : des heures sont liées à ce client" : "Supprimer"}
                          disabled={st.count > 0}
                          onClick={() => deleteClient(c)}
                          className="p-1 disabled:opacity-30"
                        ><Trash2 size={14} style={{ color: C.danger }} /></button>
                      </div>
                    </div>
                    <div className="flex gap-5 mt-3 pt-3 border-t text-xs font-mono" style={{ borderColor: "#EFEDE6", color: C.mute }}>
                      <span>{fmtHours(st.hours)} h saisies</span>
                      <span>Taux {fmtHours(num(c.taux))} CHF/h</span>
                      <span style={{ color: C.ink }}>À facturer : {fmtCHF(st.pending)}</span>
                    </div>
                  </Card>
                );
              })}
            </div>
          </div>
        )}

        {/* ---------------- FACTURATION ---------------- */}
        {tab === "facturation" && !invoiceView && (
          <div className="grid md:grid-cols-5 gap-5">
            <div className="md:col-span-2">
              <Card className="p-5">
                <div className="flex items-center gap-2 mb-4">
                  <FileText size={16} style={{ color: C.green }} />
                  <h2 className="font-display text-lg" style={{ color: C.ink }}>Générer une facture</h2>
                </div>
                <div className="space-y-3">
                  <Field label="Client">
                    <Select className="font-mono" value={invClient} onChange={(e) => setInvClient(e.target.value)}>
                      <option value="">Sélectionner…</option>
                      {allCodes.map(([code, name]) => (<option key={code} value={code}>{code} — {name}</option>))}
                    </Select>
                  </Field>
                  <div className="grid grid-cols-2 gap-3">
                    <Field label="Du"><Input type="date" className="font-mono" value={dateFrom} onChange={(e) => setDateFrom(e.target.value)} /></Field>
                    <Field label="Au"><Input type="date" className="font-mono" value={dateTo} onChange={(e) => setDateTo(e.target.value)} /></Field>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <Field label="N° de facture"><Input className="font-mono" placeholder={suggestedNumber} value={invNumber} onChange={(e) => setInvNumber(e.target.value)} /></Field>
                    <Field label="Date de facture"><Input type="date" className="font-mono" value={invDate} onChange={(e) => setInvDate(e.target.value)} /></Field>
                  </div>
                  <Field label="TVA">
                    <Select value={effectiveTva} onChange={(e) => setTvaRate(e.target.value)}>
                      <option value="0">Sans TVA</option>
                      <option value="8.1">8,1 %</option>
                      <option value="3.8">3,8 %</option>
                      <option value="2.6">2,6 %</option>
                    </Select>
                  </Field>
                  <label className="flex items-center gap-2 text-xs" style={{ color: C.mute }}>
                    <input type="checkbox" checked={includeInvoiced} onChange={(e) => setIncludeInvoiced(e.target.checked)} />
                    Inclure les heures déjà facturées
                  </label>
                  {invClient && (
                    <div className="text-xs font-mono px-3 py-2 rounded-sm" style={{ background: C.paper, color: C.mute }}>
                      {invoiceEntries.length} entrée{invoiceEntries.length > 1 ? "s" : ""} à facturer · {fmtHours(invoiceEntries.reduce((s, e) => s + e.hours, 0))} h
                    </div>
                  )}
                  <Btn disabled={!invClient || invoiceEntries.length === 0} onClick={() => setInvoiceView(buildInvoice())} className="w-full">
                    <FileText size={15} /> Aperçu de la facture
                  </Btn>
                </div>
              </Card>
            </div>

            <div className="md:col-span-3">
              <Card>
                <div className="px-4 py-3 border-b font-display text-lg" style={{ borderColor: C.line, color: C.ink }}>Factures enregistrées</div>
                {invoices.length === 0 && (
                  <div className="p-8 text-center text-sm" style={{ color: C.mute }}>Aucune facture enregistrée. Générez un aperçu puis enregistrez-le.</div>
                )}
                {invoices.map((inv) => (
                  <div key={inv.id} className="px-4 py-3 border-b flex items-center gap-3" style={{ borderColor: "#EFEDE6" }}>
                    <div className="flex-1 min-w-0">
                      <div className="text-sm font-medium"><span className="font-mono">{inv.number}</span> · {inv.client.nom}</div>
                      <div className="text-xs font-mono" style={{ color: C.mute }}>{fmtDate(inv.date)} · {inv.client.code}</div>
                    </div>
                    <div className="font-mono text-sm" style={{ color: C.ink }}>{fmtCHF(inv.total)}</div>
                    <Btn kind="secondary" onClick={() => setInvoiceView(inv)} className="!py-1">Ouvrir</Btn>
                    <button title="Supprimer (les heures redeviennent à facturer)" onClick={() => deleteInvoice(inv)}><Trash2 size={14} style={{ color: C.danger }} /></button>
                  </div>
                ))}
              </Card>
            </div>
          </div>
        )}

        {tab === "facturation" && invoiceView && (
          <div>
            <div className="no-print flex items-center justify-between mb-4 gap-2 flex-wrap">
              <button onClick={() => setInvoiceView(null)} className="text-sm flex items-center gap-1" style={{ color: C.mute }}>
                <X size={14} /> Fermer l'aperçu
              </button>
              <div className="flex gap-2">
                {!invoiceView.saved && <Btn kind="secondary" onClick={saveInvoice}><Save size={14} /> Enregistrer la facture</Btn>}
                <Btn onClick={() => window.print()}><Printer size={14} /> Imprimer / PDF</Btn>
              </div>
            </div>
            <div className="sheet-wrap overflow-x-auto"><InvoiceSheet inv={invoiceView} /></div>
          </div>
        )}

        {/* ---------------- ENTREPRISE ---------------- */}
        {tab === "fichiers" && <DriveFiles clients={clients} />}
        {tab === "entreprise" && (
          <div className="max-w-2xl">
            <Card className="p-5">
              <div className="flex items-center gap-2 mb-1">
                <Building2 size={16} style={{ color: C.green }} />
                <h2 className="font-display text-lg" style={{ color: C.ink }}>Informations de l'entreprise</h2>
              </div>
              <p className="text-xs mb-4" style={{ color: C.mute }}>Ces informations apparaissent sur chaque facture, à côté du logo.</p>
              <div className="space-y-3">
                <Field label="Nom de l'entreprise"><Input value={company.nom} onChange={(e) => setCompany({ ...company, nom: e.target.value })} /></Field>
                <div className="grid sm:grid-cols-2 gap-3">
                  <Field label="Adresse"><Input value={company.adresse} onChange={(e) => setCompany({ ...company, adresse: e.target.value })} /></Field>
                  <Field label="NPA et localité"><Input value={company.npaLocalite} onChange={(e) => setCompany({ ...company, npaLocalite: e.target.value })} /></Field>
                  <Field label="Téléphone"><Input value={company.telephone} onChange={(e) => setCompany({ ...company, telephone: e.target.value })} /></Field>
                  <Field label="E-mail"><Input type="email" value={company.email} onChange={(e) => setCompany({ ...company, email: e.target.value })} /></Field>
                  <Field label="N° IDE / TVA"><Input className="font-mono" placeholder="CHE-000.000.000" value={company.ide} onChange={(e) => setCompany({ ...company, ide: e.target.value })} /></Field>
                  <Field label="IBAN"><Input className="font-mono" placeholder="CH00 0000 0000 0000 0000 0" value={company.iban} onChange={(e) => setCompany({ ...company, iban: e.target.value })} /></Field>
                  <Field label="TVA par défaut">
                    <Select value={company.tvaRate} onChange={(e) => setCompany({ ...company, tvaRate: e.target.value })}>
                      <option value="0">Sans TVA</option>
                      <option value="8.1">8,1 %</option>
                      <option value="3.8">3,8 %</option>
                      <option value="2.6">2,6 %</option>
                    </Select>
                  </Field>
                  <Field label="Délai de paiement (jours)"><Input inputMode="numeric" className="font-mono" value={company.delaiPaiement} onChange={(e) => setCompany({ ...company, delaiPaiement: e.target.value })} /></Field>
                </div>
                <Field label="Message en bas de facture"><Input value={company.piedDePage} onChange={(e) => setCompany({ ...company, piedDePage: e.target.value })} /></Field>
              </div>
            </Card>
            <UsersPanel />
            <Card className="p-5 mt-4">
              <h3 className="font-display text-lg mb-2" style={{ color: C.ink }}>Contrôle de la QR-facture</h3>
              {qrCheck.errors.length > 0 ? (
                <div className="text-xs space-y-1" style={{ color: "#7A4B12" }}>
                  <div className="font-medium">À compléter pour que le QR apparaisse sur les factures :</div>
                  {qrCheck.errors.map((m) => (<div key={m}>• {m}</div>))}
                </div>
              ) : (
                <div className="text-xs space-y-1" style={{ color: C.mute }}>
                  <div className="font-medium" style={{ color: C.green }}>IBAN valide et adresse complète : la QR-facture sera ajoutée à chaque facture.</div>
                  <div>{qrCheck.parts.isQrIban ? "QR-IBAN détecté : une référence QRR est générée à partir du numéro de facture." : "IBAN standard : pas de référence QRR, le numéro de facture figure dans le message de paiement."}</div>
                  <div className="font-mono">Adresse lue : rue « {qrCheck.parts.street || "—"} » · n° « {qrCheck.parts.no || "—"} » · NPA {qrCheck.parts.zip} · {qrCheck.parts.town}</div>
                </div>
              )}
            </Card>
          </div>
        )}
      </div>
    </div>
  );
}
